import sys
from math import gcd
from functools import lru_cache

def solve():
    def compute_S(n, adj):
        S = [0] * (n + 1)
        for v in range(1, n + 1):
            S[v] = v
        for length in range(1, n):
            for v in range(1, n + 1):
                for u in adj[v]:
                    if S[u] < S[v] + u:
                        S[u] = S[v] + u
        return S[1:]

    def find_min_xy(a, b):
        if a == 0 and b == 0:
            return 0, 0
        g = gcd(a, b)
        a //= g
        b //= g
        return a, b

    T = int(sys.stdin.readline())
    for _ in range(T):
        N, M = map(int, sys.stdin.readline().split())
        adj = [[] for _ in range(N + 1)]
        for __ in range(M):
            x, y = map(int, sys.stdin.readline().split())
            adj[x].append(y)
            adj[y].append(x)
        S = compute_S(N, adj)
        A = min(S)
        B = max(S)
        x, y = find_min_xy(A, B)
        print(x, y)

solve()
